import numpy as np
# 인코딩 vs 임베딩: 거리가 '뜻'을 갖는가
emb = {"cat":   np.array([0.9, 0.8, 0.1]),
       "tiger": np.array([0.8, 0.9, 0.3]),
       "car":   np.array([0.1, 0.0, 0.9])}
onehot = {k: v for k, v in zip(emb, np.eye(3))}
cos = lambda a, b: a @ b / (np.linalg.norm(a) * np.linalg.norm(b))
for name, space in [("one-hot", onehot), ("embedding", emb)]:
    print(name, "cat-tiger %.3f  cat-car %.3f" %
          (cos(space["cat"], space["tiger"]), cos(space["cat"], space["car"])))
